const id = "tab_814f1e6f-a004-4ee0-8afe-4e48421fa7b1";

const navTest = await tools.browser.evaluate({ tabID: id, script: `(() => {
  document.querySelector('.nav-toggle').click();
  const nav = getComputedStyle(document.querySelector('.nav'));
  const open1 = { bodyClass: document.body.className, expanded: document.querySelector('.nav-toggle').getAttribute('aria-expanded'), visibility: nav.visibility, opacity: nav.opacity };
  document.querySelector('.nav-toggle').click();
  const closed = { bodyClass: document.body.className, expanded: document.querySelector('.nav-toggle').getAttribute('aria-expanded') };
  return { open1, closed };
})()` });

const faqTest = await tools.browser.evaluate({ tabID: id, script: `(() => {
  const btn = document.getElementById('faq-btn-1');
  btn.click();
  const panel = document.getElementById('faq-1');
  const open = { expanded: btn.getAttribute('aria-expanded'), height: panel.style.height, scrollHeight: panel.scrollHeight };
  document.getElementById('faq-btn-2').click();
  const switched = { first: btn.getAttribute('aria-expanded'), second: document.getElementById('faq-btn-2').getAttribute('aria-expanded') };
  document.getElementById('faq-btn-2').click();
  return { open, switched };
})()` });

const formTest = await tools.browser.evaluate({ tabID: id, script: `(() => {
  const form = document.getElementById('contactForm');
  form.requestSubmit();
  const invalid = [...form.querySelectorAll('[aria-invalid="true"]')].map(el => el.id);
  const errors = [...form.querySelectorAll('.field__error')].map(el => el.textContent).filter(Boolean);
  const name = form.elements.name;
  name.value = 'Camila Ortiz';
  name.dispatchEvent(new Event('input', { bubbles: true }));
  const nameErrorAfter = document.getElementById('name-error').textContent;
  return { invalid, errors, nameErrorAfter };
})()` });

return { navTest: navTest.value, faqTest: faqTest.value, formTest: formTest.value };

